'use client';

import React, { useState } from 'react';
import { VOUCHERS } from '@/data/mockData';
import { Ticket, Copy, Check } from 'lucide-react';

export default function VoucherSection() {
  const [copiedCode, setCopiedCode] = useState<string | null>(null);

  const handleCopy = (code: string) => {
    navigator.clipboard.writeText(code);
    setCopiedCode(code);
    setTimeout(() => setCopiedCode(null), 2500);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="flex items-center gap-2 mb-4">
        <Ticket className="w-5 h-5 text-[#e5677d]" />
        <h3 className="text-base font-extrabold text-neutral-900 tracking-wide uppercase">
          MÃ KHUYẾN MÃI DÀNH RIÊNG CHO BẠN
        </h3>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {VOUCHERS.map((v) => {
          const isCopied = copiedCode === v.code;
          return (
            <div
              key={v.code}
              className="relative bg-white border border-dashed border-rose-200 rounded-2xl p-4 flex items-center justify-between shadow-xs hover:border-[#e5677d] hover:shadow-md transition-all group"
            >
              <div className="space-y-1">
                <span className="text-[10px] font-bold uppercase tracking-wider text-[#e5677d] bg-pink-50 px-2 py-0.5 rounded-full">
                  MÃ: {v.code}
                </span>
                <h4 className="text-sm font-black text-neutral-900 group-hover:text-[#e5677d] transition-colors">
                  {v.title}
                </h4>
                <p className="text-xs text-neutral-500">{v.desc}</p>
              </div>

              <button
                onClick={() => handleCopy(v.code)}
                className={`flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                  isCopied
                    ? 'bg-emerald-600 text-white'
                    : 'bg-neutral-900 text-white hover:bg-[#e5677d]'
                }`}
              >
                {isCopied ? (
                  <>
                    <Check className="w-3.5 h-3.5" />
                    <span>ĐÃ LƯU</span>
                  </>
                ) : (
                  <>
                    <Copy className="w-3.5 h-3.5" />
                    <span>LƯU MÃ</span>
                  </>
                )}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

